mod tests {
    use super::*;

    #[test]
    fn test_palindromes() {
        assert!(is_palindrome("Racecar"));
        assert!(is_palindrome("A man, a plan, a canal: Panama"));
        assert!(is_palindrome(""));
        assert!(is_palindrome("a"));
    }

    #[test]
    fn test_non_palindromes() {
        assert!(!is_palindrome("Rust"));
        assert!(!is_palindrome("hello world"));
    }
}
